/** Regenerate the console's SDK-free credential-key catalogue from the installed pinned pi (#751). */
import { readFileSync, writeFileSync } from "node:fs";
import { createHash } from "node:crypto";
import { fileURLToPath, pathToFileURL } from "node:url";
import { dirname, join, resolve } from "node:path";

export const PROVIDER_KEYS_FILE = "admin/src/provider-key-names.mjs";
export function providerKeysSource(keys, sha) {
	return `/** GENERATED by .github/scripts/provider-key-names.mjs from pinned pi; do not edit the table.\n * A data-only leaf keeps provider SDKs out of the console. The hash and exhaustive derivation test gate upgrades.\n */\nexport const PROVIDER_KEYS_SOURCE_SHA256 = ${JSON.stringify(sha)};\nexport const PROVIDER_KEY_NAMES = Object.freeze(${JSON.stringify(keys, null, 2)});\nexport function providerKeyNames(provider) { return Object.hasOwn(PROVIDER_KEY_NAMES, provider) ? [...PROVIDER_KEY_NAMES[provider]] : []; }\n`;
}

export async function generateProviderKeys() {
	const { providerKeyCandidates, piProviders } = await import("../../worker/src/env-allowlist.mjs");
	const { piOwnPackageDir } = await import("../../image/runner/src/usage-meter.mjs");
	const source = readFileSync(join(piOwnPackageDir("pi-ai"), "dist/env-api-keys.js"));
	const keys = Object.fromEntries(piProviders().sort().map((name) => [name, providerKeyCandidates(name)]));
	return providerKeysSource(keys, createHash("sha256").update(source).digest("hex"));
}

if (process.argv[1] && import.meta.url === pathToFileURL(resolve(process.argv[1])).href) {
	const file = join(dirname(fileURLToPath(import.meta.url)), "../..", PROVIDER_KEYS_FILE);
	const generated = await generateProviderKeys();
	if (process.argv.includes("--write")) writeFileSync(file, generated);
	else if (readFileSync(file, "utf8") !== generated) throw new Error(`${PROVIDER_KEYS_FILE} differs from pinned pi; inspect its source and run node .github/scripts/provider-key-names.mjs --write`);
}
